# Tale's End: Sublime Epiphany's "Counter target activated or triggered ability" filter, widened
# by "or legendary spell" (Miscast's typed-spell shape: the spell kind AND the card property).
# The compiler gave no tree at all; the instant carrier is added.
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=A(Verb.COUNTER_SPELL, {
            'target': Selector(
                count=QConst(value=1),
                mode=SelectorMode.TARGET,
                filter=FOr(children=(
                    FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='ACTIVATED'),
                    FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='TRIGGERED'),
                    FAnd(children=(
                        FAtom(pred=FAtomPred.SUPERTYPE_EQ, string_value='Legendary'),
                        FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='SPELL'),
                    )),
                )),
                zones=(Zone(kind=ZoneKind.STACK, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
